#!/usr/bin/env python3
"""crispr/base_editor_design — auto-generated run.py (archetype=crispr).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "crispr"
BRAIN = "crispr"
SKILL = "base_editor_design"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'base_editor_design', 'n_guides': 0, 'guides_csv': '', 'best_guide': {'seq': '', 'cfd_score': 0.0, 'mit_score': 0.0}, 'diagnostics': {'brain': 'crispr', 'archetype': 'crispr'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """Base editor 设计:扫 target 找 sgRNA 满足 editing window 内只有目标 C(C->T)且 PAM 适配。
    host_env=PRAXIS-CRISPR。
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401
    seq = payload.get("target_sequence")
    target_pos = int(payload.get("target_position", -1))  # 0-based 在 sequence 内
    editor = payload.get("editor", "ABE")  # ABE | CBE
    window = payload.get("editing_window", [4, 8])
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "editor": editor, "window": window}
    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "n_guides": 0, "guides_csv": "",
                "best_guide": {"seq": "", "cfd_score": 0.0, "mit_score": 0.0},
                "diagnostics": {**diagnostics, "dry": True}}
    if not seq or target_pos < 0:
        return {"ok": False, "error": "需要 target_sequence + target_position", "diagnostics": diagnostics}
    import re as _re
    seq_u = seq.upper()
    wt_base = seq_u[target_pos] if 0 <= target_pos < len(seq_u) else "N"
    if editor == "ABE" and wt_base != "A":
        return {"ok": False, "error": f"ABE 需要 target=A,实际={wt_base}", "diagnostics": diagnostics}
    if editor == "CBE" and wt_base != "C":
        return {"ok": False, "error": f"CBE 需要 target=C,实际={wt_base}", "diagnostics": diagnostics}
    candidates = []
    for m in _re.finditer(r"(?=([ACGT]{20}.GG))", seq_u):
        spacer = m.group(1)[:20]
        start = m.start()
        # editing window 在 spacer 内位置(1-based)
        rel = target_pos - start + 1
        if window[0] <= rel <= window[1]:
            candidates.append({"protospacer": spacer, "start": start, "rel_pos_in_window": rel,
                              "pam": m.group(1)[20:]})
    best = candidates[0] if candidates else None
    return {"ok": True, "skill_id": SKILL,
            "n_guides": len(candidates), "guides_csv": "",
            "best_guide": {"seq": best["protospacer"] if best else "",
                          "cfd_score": 0.0, "mit_score": 0.0},
            "candidates": candidates[:10], "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
